const aliases = new Set();
const output = [];
for (const [difficulty,tags,names] of groups) {
  for (const rawName of names.split('|')) {
    const name = rawName.trim();
    if (aliases.has(name)) continue;
    aliases.add(name);
    output.push({id:`p${String(output.length+1).padStart(3,'0')}`,name,difficulty,tags});
  }
}
// Avoid aliases for a player appearing twice in the same match.
export const PLAYERS = output.filter(p=>!['ريكاردو كاكا','عبد العزيز الحبسي'].includes(p.name)).map(p=>({
  ...p,
  name: ({'دروغبا':'ديدييه دروغبا','كييليني':'جورجيو كييليني','حجي':'غيورغي هاجي','كينيني دالغليش':'كيني دالغليش','غيلمن ميندييتا':'غايزكا ميندييتا','جمال بلاضي':'جمال بلماضي'}[p.name]||p.name),
  tags:p.name==='أشرف بن شرقي'?['arab','world']:p.tags,
}));
export const DIFFICULTY = {easy:'سهل',medium:'متوسط',hard:'للخبراء'};
export const CATEGORIES = {all:'كل الملاعب',world:'أوروبا والعالم',arab:'نجوم عرب',legends:'أساطير اللعبة',custom:'أسماؤكم الخاصة'};
